import React, { useCallback, useState } from 'react';
import { AppEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { Action } from '@thoughtspot/visual-embed-sdk';
import { useTier } from '../config/TierContext';

export default function Reports() {
  const [embedError, setEmbedError] = useState<string | null>(null);
  const { hiddenActions, disabledActions } = useTier();

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    const msg =
      err?.data?.errorMessage ||
      err?.message ||
      (typeof err === 'object' ? JSON.stringify(err) : String(err));
    setEmbedError(msg);
    console.error('[ThoughtSpot AppEmbed]', err);
  }, []);

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#F3F4F6', display: 'flex', flexDirection: 'column' }}>
      <div style={{ padding: '2rem 2.5rem 1rem' }}>
        <h1 style={{ fontSize: 26, fontWeight: 700, color: '#111827', margin: 0 }}>Reports</h1>
        <p style={{ fontSize: 13.5, color: '#6B7280', margin: '4px 0 0' }}>
          Your saved liveboards and reports
        </p>
      </div>

      <div style={{ padding: '0 2.5rem 2rem', flex: 1, display: 'flex', flexDirection: 'column' }}>
        {embedError && (
          <div
            role="alert"
            style={{
              marginBottom: '1rem',
              padding: '0.75rem 1rem',
              background: '#FEF2F2',
              border: '1px solid #FECACA',
              borderRadius: 8,
              fontSize: 14,
              color: '#991B1B',
            }}
          >
            <strong>Embed error:</strong> {embedError}
          </div>
        )}

        <div
          style={{
            backgroundColor: '#fff',
            borderRadius: 12,
            border: '1px solid #E5E7EB',
            overflow: 'hidden',
            flex: 1,
            minHeight: 'calc(100vh - 160px)',
          }}
        >
          <AppEmbed
            path="insights/home/liveboards"
            showPrimaryNavbar={false}
            hiddenActions={[
              ...hiddenActions,
              Action.EditACopy,
              Action.MakeACopy,
            ]}
            disabledActions={disabledActions}
            onError={onError}
            additionalFlags={{
              myLibraryDefaultTab: 'MY_LIVEBOARDS',
            }}
            style={{ width: '100%', height: 'calc(100vh - 160px)' }}
          />
        </div>
      </div>
    </div>
  );
}
